// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, uint256 depositCount) public {
        amount = bound(amount, 0, type(uint128).max);
        depositCount = bound(depositCount, 1, 10);
        for (uint i = 0; i < depositCount; i++) {
            vm.deal(address(this), amount + 1e18);
            (bool ok, ) = address(c).call{value: amount}("");
            assertTrue(ok);
        }
        assertTrue(c.depositsCount() == depositCount);
    }
}
